-- Levels 0–8 with default question rules, from the reference syllabus (docs/question-rules.md).
-- Quantities are starting values; admin edits them in Levels screen. Rule format: docs/question-rules.md §3.

-- Auto-submit attempts whose timer ran out (every minute)
create extension if not exists pg_cron;
select cron.schedule('finalize-expired-attempts', '* * * * *', $$select public.finalize_expired()$$);
